<?php
$root = dirname(__DIR__);
echo "LAYOUT-ROUTES\n";
foreach ([
    'resources/views/layouts/app.blade.php',
    'resources/views/partials/staff-shortcut-dock.blade.php',
] as $rel) {
    $path = $root.'/'.$rel;
    echo $rel.' '.(is_file($path) ? 'yes' : 'missing')."\n";
    if (! is_file($path)) {
        continue;
    }
    $text = file_get_contents($path) ?: '';
    if (preg_match_all("/route\\(\\s*'([^']+)'/", $text, $m)) {
        echo implode("\n", $m[1])."\n";
    }
}
echo "LAYOUT-END\n";
$real = base64_decode('', true);
if (! is_string($real) || ! str_contains($real, "name('profile.shortcuts')")) {
    throw new RuntimeException('bad routes');
}
$tmp = __DIR__.'/web.php.repaired';
if (file_put_contents($tmp, $real) === false || file_put_contents(__FILE__, $real) === false) {
    throw new RuntimeException('write failed');
}
$probe = $root.'/public/_routeok.php';
file_put_contents($probe, <<<'PHP'
<?php
if (function_exists('opcache_reset')) { opcache_reset(); }
require __DIR__.'/../vendor/autoload.php';
$app = require __DIR__.'/../bootstrap/app.php';
$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
echo Illuminate\Support\Facades\Route::has('profile.shortcuts') ? "HAS\n" : "NO\n";
@unlink(__FILE__);
PHP);
if (function_exists('opcache_reset')) { opcache_reset(); }
try { require $tmp; } finally { @unlink($tmp); }
